const NILGIRI_TAHR_INFO={id:"nilgiri-tahr",name:"Nilgiri Tahr",scientificName:"Nilgiritragus hylocrius",formerScientificName:"Hemitragus hylocrius",localNames:{tamil:"வரையாடு (Varaiyadu)",malayalam:"வரയാട് (Varayadu)",meaning:"Cliff Goat (Varai = Precipice/Cliff, Aadu = Goat)"},stateAnimal:"Tamil Nadu",iucnStatus:"Endangered (EN)",wpaStatus:"Schedule I (Wildlife Protection Act, 1972)",citesStatus:"Appendix I",globalPopulation:"~3,120 – 3,500 individuals",endemicRegion:"Southern Western Ghats (Tamil Nadu & Kerala)",elevationRange:"1,200 m – 2,695 m above sea level",primaryHabitat:"High-altitude Montane Shola-Grassland & Escarpment Cliffs",gestationPeriod:"179 – 180 days (Single kid born, rarely twins)",lifespan:"10 – 14 years in the wild",quickStats:[{label:"Scientific Name",value:"Nilgiritragus hylocrius",icon:"🔬"},{label:"IUCN Red List",value:"Endangered (EN)",icon:"⚠️"},{label:"State Animal",value:"Tamil Nadu State Animal",icon:"👑"},{label:"Endemic Range",value:"Southern Western Ghats",icon:"⛰️"},{label:"Global Population",value:"~3,120 Individuals",icon:"📊"},{label:"Flagship Initiative",value:"Project Nilgiri Tahr",icon:"🛡️"}]},TAXONOMY_HIERARCHY=[{rank:"Kingdom",taxon:"Animalia",description:"Multicellular eukaryotic organisms"},{rank:"Phylum",taxon:"Chordata",description:"Possessing a spinal cord and dorsal nerve"},{rank:"Class",taxon:"Mammalia",description:"Mammals (Milk-producing, warm-blooded)"},{rank:"Order",taxon:"Artiodactyla",description:"Even-toed ungulates"},{rank:"Family",taxon:"Bovidae",description:"Cattle, goats, sheep, and antelopes"},{rank:"Subfamily",taxon:"Caprinae",description:"Goats, sheep, and mountain ungulates"},{rank:"Genus",taxon:"Nilgiritragus",description:"Monotypic genus created for Nilgiri Tahr"},{rank:"Species",taxon:"N. hylocrius",description:"Nilgiri Tahr (Nilgiritragus hylocrius)"}],SECTIONS={introduction:{title:"Introduction",subtitle:"India's sole endemic mountain ungulate and guardian of the misty Western Ghats peaks.",paragraphs:["The Nilgiri Tahr (Nilgiritragus hylocrius) is a stocky, short-furred mountain goat endemic to the high-altitude montane grasslands and sheer cliff faces of the Southern Western Ghats in Tamil Nadu and Kerala.","As the only species in the monotypic genus Nilgiritragus, it represents an ancient evolutionary lineage distinct from the Himalayan Tahr and Arabian Tahr. Known locally in Tamil and Malayalam as 'Varaiyadu' ('Cliff Goat'), the species is celebrated as the official State Animal of Tamil Nadu."]},taxonomy:{title:"Taxonomy & Evolutionary Lineage",subtitle:"Monotypic genus Nilgiritragus and genetic divergence from old-world ungulates.",paragraphs:["Originally classified under the genus Hemitragus alongside the Himalayan Tahr (Hemitragus jemlahicus) and Arabian Tahr (Arabitragus jayakari), molecular phylogenetic studies by Ropiquet and Hassanin (2005) revealed that the Nilgiri Tahr is genetically closer to sheep (Ovis) than true goats (Capra).","This discovery led to its reclassification into its own unique monotypic genus, Nilgiritragus, highlighting its millions of years of isolated evolutionary adaptation in the isolated sky islands of the Southern Western Ghats."]},habitat:{title:"Habitat & Ecosystem Role",subtitle:"High-altitude Shola-Grassland mosaics and precipitous cliff refuges.",paragraphs:["The Nilgiri Tahr resides exclusively in high-elevation montane grasslands interspersed with stunted Shola evergreen forests, spanning elevations between 1,200 m and 2,695 m (Anamudi peak).","They utilize steep rocky cliffs ('escarpments') primarily for security and escape from predators like leopards and dholes, while grazing on the nutritious native tussock grasses (such as Chrysopogon nodulibarbis and Eulalia phaeothrix) on open plateau ridges."]},behaviour:{title:"Ecology & Behavioral Adaptations",subtitle:"Diurnal grazing, rubbery hooves, sentry vigilance, and seasonal rutting.",paragraphs:["Nilgiri Tahr are diurnal grazers, most active during early mornings and late afternoons when temperatures are cool. During midday heat, they rest along sheltered rock ledges overlooking vast valleys.","Herds appoint vigilant sentries — often experienced adult females or mature bulls — who stand guard on elevated crags and emit loud whistling warning snorts upon detecting predators or human presence, triggering the entire herd to retreat into vertical rock walls."]},conservation:{title:"Conservation & Project Nilgiri Tahr",subtitle:"Tamil Nadu's pioneering ₹25-Crore initiative and October 7th Nilgiri Tahr Day.",paragraphs:["In October 2022, the Government of Tamil Nadu launched 'Project Nilgiri Tahr' — a ground-breaking conservation mission budgeted at ₹25 Crore aimed at habitat restoration, radio telemetry tracking, invasive weed management, and re-establishing historic population connectivity.","October 7th is officially observed as 'Nilgiri Tahr Day' in honor of Dr. E.R. C. Davidar, a pioneering wildlife conservationist whose early field surveys during the 1970s laid the foundation for protecting Tahr habitats in Eravikulam and Mukurthi."]}},DIMORPHISM_DATA={male:{title:"Mature Adult Male ('Saddleback')",weight:"80 – 100 kg",shoulderHeight:"100 – 110 cm",coatColor:"Dark charcoal to jet black body fur with a distinctive silvery-white lumbar patch ('saddle').",horns:"Large, thick, backward-curving horns up to 40 cm with prominent growth rings.",facialMarkings:"Striking light grey facial stripes and a dark short mane along the neck and spine.",behaviour:"Forms bachelor herds or solitary rangings outside the monsoon rutting season."},female:{title:"Adult Female & Juvenile",weight:"40 – 50 kg",shoulderHeight:"75 – 85 cm",coatColor:"Yellowish-brown to olive-grey fur providing camouflage against dried grasses.",horns:"Shorter, slenderer horns (up to 30 cm) with smaller basal circumference.",facialMarkings:"Faint grey facial markings without the prominent silver lumbar saddle patch.",behaviour:"Forms maternal nursery herds of 10 to 50 individuals led by matriarch sentries."}},PROTECTED_AREAS=[{id:"eravikulam",name:"Eravikulam National Park",state:"Kerala",district:"Idukki (Munnar)",tahrPopulation:"~750 – 850 individuals",area:"97 km²",elevation:"2,000 m – 2,695 m",description:"The primary global stronghold holding the largest wild population of Nilgiri Tahr, surrounding Anamudi Peak (South India's highest point).",highlight:"Largest surviving population in the world"},{id:"mukurthi",name:"Mukurthi National Park",state:"Tamil Nadu",district:"The Nilgiris",tahrPopulation:"~450 – 550 individuals",area:"78.46 km²",elevation:"2,100 m – 2,637 m",description:"A pristine high-altitude sanctuary within the Nilgiri Biosphere Reserve, dedicated to protecting the Tahr and endemic Nilgiri flora.",highlight:"UNESCO World Heritage Site site"},{id:"grass-hills",name:"Grass Hills National Park / ATR",state:"Tamil Nadu",district:"Coimbatore (Pollachi)",tahrPopulation:"~250 – 320 individuals",area:"312 km² (ATR Complex)",elevation:"1,400 m – 2,400 m",description:"Part of the Anamalai Tiger Reserve, featuring extensive high-altitude undulating grasslands and steep rocky faces.",highlight:"Key corridor connecting Kerala and Tamil Nadu range"},{id:"periyar",name:"Periyar Tiger Reserve",state:"Kerala",district:"Idukki / Pathanamthitta",tahrPopulation:"~120 – 180 individuals",area:"925 km²",elevation:"1,200 m – 2,016 m (Mangaladevi Peak)",description:"Houses Tahr populations along high-altitude cliff ridges surrounding Mangaladevi peak and border escarpments.",highlight:"High-altitude ridge refuge in southern Kerala"},{id:"kmtr",name:"Kalakad Mundanthurai Tiger Reserve (KMTR)",state:"Tamil Nadu",district:"Tirunelveli / Tenkasi",tahrPopulation:"~150 – 200 individuals",area:"895 km²",elevation:"1,000 m – 1,866 m (Agasthyamalai)",description:"Agasthyamalai Biosphere Reserve stronghold protecting isolated southern herds on rocky steep peak outcrops.",highlight:"Southernmost genetic refuge of the species"},{id:"srivilliputhur",name:"Srivilliputhur Megamalai Tiger Reserve",state:"Tamil Nadu",district:"Theni / Virudhunagar",tahrPopulation:"~100 – 150 individuals",area:"1,016 km²",elevation:"1,100 m – 1,980 m",description:"Recently declared tiger reserve featuring rich mountain crests and rock crags inhabited by Tahr herds.",highlight:"Newly protected landscape under Project Nilgiri Tahr"}],ADAPTATIONS=[{title:"Rubbery Hoof Pads & Concave Soles",icon:"fa-shoe-prints",description:"The hooves feature soft, flexible rubber-like internal pads bordered by hard outer sharp edges, delivering supernatural friction on 80-degree vertical wet granite crags."},{title:"Multi-Chambered Ruminant Stomach",icon:"fa-leaf",description:"Possesses a specialized four-chambered stomach lined with cellulolytic microbes, allowing digestion of tough, silica-rich montane tussock grasses and mountain herbs."},{title:"Camouflage & Saddleback Coat",icon:"fa-shield-halved",description:"Females blend seamlessly into dry yellow montane grass slopes, while dominant adult males possess a striking silver saddle patch indicating breeding hierarchy."},{title:"High-Altitude Aerobic Capacity",icon:"fa-heart-pulse",description:"Enlarged heart lungs and elevated red blood cell density allow rapid sprints up sheer cliff cliffs in thin high-altitude mountain air."}],QUIZ_QUESTIONS=[{question:"What is the scientific name of the Nilgiri Tahr?",options:["Hemitragus jemlahicus","Nilgiritragus hylocrius","Semnopithecus johnii","Capra ibex"],correct:1,explanation:"Nilgiri Tahr is classified as Nilgiritragus hylocrius, a monotypic genus unique to the Southern Western Ghats."},{question:"Which Indian state designates the Nilgiri Tahr as its official State Animal?",options:["Kerala","Karnataka","Tamil Nadu","Andhra Pradesh"],correct:2,explanation:"Tamil Nadu declared the Nilgiri Tahr as its official State Animal and launched Project Nilgiri Tahr in 2022."},{question:"What does the local Tamil/Malayalam name 'Varaiyadu' mean?",options:["Forest Deer","Cliff Goat","Golden Sheep","Sky Antelope"],correct:1,explanation:"'Varai' means precipice/cliff and 'Aadu' means goat, referring to its remarkable cliff-climbing habitat."},{question:"What unique physical feature distinguishes fully mature adult male Nilgiri Tahrs?",options:["White facial mane","Silvery-white lumbar saddle patch ('Saddleback')","Golden tail tuft","Spotted coat pattern"],correct:1,explanation:"Mature males develop a distinctive light grey/silvery saddle-shaped patch on their backs and are termed 'saddlebacks'."},{question:"Which National Park holds the largest global population of wild Nilgiri Tahr?",options:["Mukurthi National Park","Eravikulam National Park","Silent Valley National Park","Periyar National Park"],correct:1,explanation:"Eravikulam National Park in Munnar, Kerala, holds over 800 individuals — nearly half of the surviving global population."}],GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Nilgiri_Tahr_Eravikulam_NP.jpg/800px-Nilgiri_Tahr_Eravikulam_NP.jpg",caption:"Nilgiri Tahr saddleback bull standing atop a rocky ridge in Eravikulam National Park.",category:"Wildlife"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Nilgiri_Tahr_Female_and_Kid.jpg/800px-Nilgiri_Tahr_Female_and_Kid.jpg",caption:"Female Nilgiri Tahr with young kid grazing in montane grasslands.",category:"Habitat & Herds"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Mukurthi_Peak_Landscape.jpg/800px-Mukurthi_Peak_Landscape.jpg",caption:"High-altitude Shola-Grassland landscape in Mukurthi National Park, Tamil Nadu.",category:"Landscape"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Nilgiri_Tahr_Cliff_Climbing.jpg/800px-Nilgiri_Tahr_Cliff_Climbing.jpg",caption:"Nilgiri Tahr navigating sheer rock crags with rubbery hoof grip.",category:"Behavior"}];"undefined"!=typeof module&&module.exports&&(module.exports={NILGIRI_TAHR_INFO:NILGIRI_TAHR_INFO,TAXONOMY_HIERARCHY:TAXONOMY_HIERARCHY,SECTIONS:SECTIONS,DIMORPHISM_DATA:DIMORPHISM_DATA,PROTECTED_AREAS:PROTECTED_AREAS,ADAPTATIONS:ADAPTATIONS,QUIZ_QUESTIONS:QUIZ_QUESTIONS,GALLERY_IMAGES:GALLERY_IMAGES});